9	// TestNormalizeGreeter_NilReceiver — defensivo, igual que NormalizeTickets.
10	func TestNormalizeGreeter_NilReceiver(t *testing.T) {
11		NormalizeGreeter(nil) // no debe entrar en pánico
12	}
13	
14	// legacyGreeter reproduce lo que Mongo devuelve para un guild v9/v10: bloques
15	// que existen pero nunca se escribieron enteros, así que decodifican al valor
16	// cero de Go — enums vacíos, slices nil y un lienzo 0x0.
17	func legacyGreeter() ModuleGreeter {
18		return ModuleGreeter{
19			SchemaVersion: 9,
20			Enabled:       true,
21			Welcome: GreeterMessageConfig{
22				Enabled: true,
23				Message: GreeterMessage{Content: "¡Hola {user}!"},
24			},
25		}
26	}
27	
28	// TestNormalizeGreeter_LegacyDoc 🛡️ — un doc legacy sale del normalizador con
29	// la forma que el dashboard y el bot esperan. Sin esto: `mode: ""` no casa con
30	// ningún modo del renderer (el bot no publica nada mientras el dashboard lo
31	// pinta como `plain`), y `elements: null` revienta el `.map()` del dashboard y
32	// el `for..of` del bot.
33	func TestNormalizeGreeter_LegacyDoc(t *testing.T) {
34		g := legacyGreeter()
35		NormalizeGreeter(&g)
36	
37		if g.Welcome.Message.Mode != GreeterModePlain {
38			t.Fatalf("welcome.message.mode = %q, want %q", g.Welcome.Message.Mode, GreeterModePlain)
39		}
40		if g.Welcome.DM.Message.Mode != GreeterModePlain {
41			t.Fatalf("welcome.dm.message.mode = %q, want %q", g.Welcome.DM.Message.Mode, GreeterModePlain)
42		}
43		if g.Welcome.Image.Mode != GreeterImageBasic {
44			t.Fatalf("welcome.image.mode = %q, want %q", g.Welcome.Image.Mode, GreeterImageBasic)
45		}
46		if g.Welcome.Image.Canvas.Elements == nil {
47			t.Fatal("welcome.image.canvas.elements sigue nil (emitiría null en JSON)")
48		}
49		if g.Welcome.Image.Canvas.Width != 1024 || g.Welcome.Image.Canvas.Height != 500 {
50			t.Fatalf("canvas = %dx%d, want 1024x500", g.Welcome.Image.Canvas.Width, g.Welcome.Image.Canvas.Height)
51		}
52		if g.JoinRoles.RolesID == nil {
53			t.Fatal("join_roles.roles_id sigue nil")
54		}
55		if len(g.Variables.Allowed) != len(DefaultGreeterVariables()) {
56			t.Fatalf("variables.allowed = %v, want los %d por defecto", g.Variables.Allowed, len(DefaultGreeterVariables()))
57		}
58		// Goodbye y boost reciben el mismo trato.
59		if g.Goodbye.Message.Mode != GreeterModePlain || g.Boost.Message.Mode != GreeterModePlain {
60			t.Fatalf("goodbye/boost mode = %q/%q, want plain", g.Goodbye.Message.Mode, g.Boost.Message.Mode)
61		}
62	}
63	
64	// TestNormalizeGreeter_NoClobber 🛡️ — normalizar NO puede pisar configuración
65	// existente. Es la diferencia entre migrar un doc legacy y resetearlo: para un
66	// v9 con ajustes reales, sustituirlo por los defaults borraría el trabajo del
67	// usuario.
68	func TestNormalizeGreeter_NoClobber(t *testing.T) {
69		g := legacyGreeter()
70		g.Welcome.Message.Mode = GreeterModeEmbedImage
71		g.Welcome.Image.Mode = GreeterImageAdvanced
72		g.Welcome.Image.Canvas.Width = 640
73		g.Welcome.Image.Canvas.Height = 360
74		g.Welcome.Image.Canvas.Elements = []GreeterImageElement{{ID: "e1", Type: "text"}}
75		g.JoinRoles.RolesID = []string{"role1"}
76		g.Variables.Allowed = []string{"user"}
77	
78		NormalizeGreeter(&g)
79	
80		if g.Welcome.Message.Mode != GreeterModeEmbedImage {
81			t.Fatalf("mode pisado: %q", g.Welcome.Message.Mode)
82		}
83		if g.Welcome.Image.Mode != GreeterImageAdvanced {
84			t.Fatalf("image.mode pisado: %q", g.Welcome.Image.Mode)
85		}
86		if g.Welcome.Image.Canvas.Width != 640 || g.Welcome.Image.Canvas.Height != 360 {
87			t.Fatalf("canvas pisado: %dx%d", g.Welcome.Image.Canvas.Width, g.Welcome.Image.Canvas.Height)
88		}
89		if len(g.Welcome.Image.Canvas.Elements) != 1 || g.Welcome.Image.Canvas.Elements[0].ID != "e1" {
90			t.Fatalf("elements pisados: %v", g.Welcome.Image.Canvas.Elements)
91		}
92		if len(g.JoinRoles.RolesID) != 1 || g.JoinRoles.RolesID[0] != "role1" {
93			t.Fatalf("roles_id pisados: %v", g.JoinRoles.RolesID)
94		}
95		if len(g.Variables.Allowed) != 1 {
96			t.Fatalf("variables.allowed pisadas: %v", g.Variables.Allowed)
97		}
98		// Y el contenido del mensaje, que es lo que de verdad duele perder.
99		if g.Welcome.Message.Content != "¡Hola {user}!" {
100			t.Fatalf("content pisado: %q", g.Welcome.Message.Content)
101		}
102	}
103	
104	// TestNormalizeGreeter_Idempotent — aplicarlo dos veces da el mismo resultado.
105	func TestNormalizeGreeter_Idempotent(t *testing.T) {
106		g := legacyGreeter()
107		NormalizeGreeter(&g)
108		first, err := json.Marshal(g)
109		if err != nil {
110			t.Fatalf("marshal: %v", err)
111		}
112		NormalizeGreeter(&g)
113		second, err := json.Marshal(g)
114		if err != nil {
115			t.Fatalf("marshal: %v", err)
116		}
117		if string(first) != string(second) {
118			t.Fatalf("no idempotente:\n1: %s\n2: %s", first, second)
119		}
120	}
121	
122	// TestModuleGreeter_CaptchaEmitsNull 🛡️ — `captcha` nulo tiene que salir como
123	// `null`, NO desaparecer del JSON. La regla del fichero es que la salida
124	// conserve la forma del tipo TS: con `omitempty` en el tag json, un consumidor
125	// que leyera `data.captcha.enabled` recibía `undefined` en vez de `null` y
126	// petaba con un TypeError. `captcha` era el único nullable del greeter con
127	// omitempty en json; el resto (`enabled_since`, `channel_id`…) ya emitían null.
128	func TestModuleGreeter_CaptchaEmitsNull(t *testing.T) {
129		var g ModuleGreeter
130		g.Captcha = nil
131	
132		b, err := json.Marshal(g)
133		if err != nil {
134			t.Fatalf("marshal: %v", err)
135		}
136	
137		var raw map[string]json.RawMessage
138		if err := json.Unmarshal(b, &raw); err != nil {
139			t.Fatalf("unmarshal: %v", err)
140		}
141		v, ok := raw["captcha"]
142		if !ok {
143			t.Fatalf("la clave `captcha` no aparece en el JSON: %s", b)
144		}
145		if string(v) != "null" {
146			t.Fatalf("captcha = %s, want null", v)
147		}
148	}
149	
150	// radiusPtrForTest fabrica un *float64 para poblar `Radius` en los tests de
151	// migración — mismo molde que boolPtrForTest en module_modmail_test.go.
152	func radiusPtrForTest(v float64) *float64 { return &v }
153	
154	// greeterElementWithRadius monta el ModuleGreeter mínimo que
155	// normalizeGreeterMessageConfig necesita para reescalar UN elemento del
156	// canvas de welcome: SchemaVersion legacy (cualquier valor por debajo de
157	// SchemaVersionGreeter sirve; NormalizeGreeter no la mira) y un único
158	// elemento con su PROPIA caja `width`x`height` -la que manda según el
159	// contrato, no la del canvas-.
160	func greeterElementWithRadius(elemType string, width, height float64, radius *float64) ModuleGreeter {
161		return ModuleGreeter{
162			SchemaVersion: 9,
163			Welcome: GreeterMessageConfig{
164				Image: GreeterImage{
165					Canvas: GreeterImageCanvas{
166						Elements: []GreeterImageElement{
167							{ID: "e1", Type: elemType, Width: width, Height: height, Radius: radius},
168						},
169					},
170				},
171			},
172		}
173	}
174	
175	// TestNormalizeGreeter_RadiusPxToPercent 🛡️ — v13: el mismo número de
176	// `radius` pasa a significar otra cosa (porcentaje del lado corto DEL
177	// ELEMENTO, no del canvas, en vez de píxeles), así que NormalizeGreeter tiene
178	// que reescalar cada valor YA guardado con la fórmula del contrato
179	// (`pct = round(clamp(px / (min(w,h)/2) * 100, 0, 100))`) en vez de
180	// limitarse a rellenar huecos. Cubre: el sentinela viejo de "redondo del
181	// todo" (9999px, el que usaban avatares/círculos), un valor intermedio real,
182	// el cero, la ausencia de valor (no se inventa un dato que el usuario nunca
183	// puso) y una caja degenerada (ancho o alto 0) que no debe dar +Inf/NaN.
184	func TestNormalizeGreeter_RadiusPxToPercent(t *testing.T) {
185		cases := []struct {
186			name          string
187			elemType      string
188			width, height float64
189			radius        *float64
190			want          *float64
191		}{
192			// (a) avatar 200x200 con el sentinela viejo 9999px -> clamp a 100.
193			{"sentinel avatar 9999px", "avatar", 200, 200, radiusPtrForTest(9999), radiusPtrForTest(100)},
194			// (b) figura 220x130 con 12px -> 12 / 65 * 100 = 18.46... -> 18.
195			{"figura 220x130 con 12px", "shape", 220, 130, radiusPtrForTest(12), radiusPtrForTest(18)},
196			// (c) 0px sigue 0.
197			{"cero sigue cero", "image", 200, 200, radiusPtrForTest(0), radiusPtrForTest(0)},
198			// (d) nil no se inventa un valor.
199			{"nil no se inventa", "image", 200, 200, nil, nil},
200			// (e) caja degenerada (ancho 0) -> 0, nunca +Inf/NaN.
201			{"ancho cero", "shape", 0, 130, radiusPtrForTest(12), radiusPtrForTest(0)},
202			// (e) caja degenerada (alto 0) -> 0.
203			{"alto cero", "shape", 220, 0, radiusPtrForTest(12), radiusPtrForTest(0)},
204		}
205		for _, c := range cases {
206			t.Run(c.name, func(t *testing.T) {
207				g := greeterElementWithRadius(c.elemType, c.width, c.height, c.radius)
208				NormalizeGreeter(&g)
209	
210				got := g.Welcome.Image.Canvas.Elements[0].Radius
211				if c.want == nil {
212					if got != nil {
213						t.Fatalf("radius = %v, want nil", *got)
214					}
215					return
216				}
217				if got == nil {
218					t.Fatalf("radius = nil, want %v", *c.want)
219				}
220				if *got != *c.want {
221					t.Fatalf("radius = %v, want %v", *got, *c.want)
222				}
223				// El resultado tiene que ser siempre finito -las cajas
224				// degeneradas de arriba no pueden colarse como +Inf/NaN.
225				if math.IsNaN(*got) || math.IsInf(*got, 0) {
226					t.Fatalf("radius = %v no es finito", *got)
227				}
228			})
229		}
230	}
231	
232	// TestNormalizeGreeter_RadiusMigrationIsVersionScoped 🛡️ — el guard de versión
233	// vive DENTRO de NormalizeGreeter y mira la versión del DOCUMENTO
234	// (`SchemaVersionGreeterRadiusPercent`), no la del código.
235	//
236	// Antes lo ponía el llamador con `SchemaVersion < SchemaVersionGreeter`, y eso
237	// protegió exactamente mientras la constante valió 13: al subirla a 14 y a 15,
238	// un documento ya migrado volvía a colarse por ese guard y se reescalaba una
239	// segunda vez. Este test fija que el reescalado depende de dónde está el
240	// documento, y que aplicarlo dos veces ya no puede deformar nada.
241	func TestNormalizeGreeter_RadiusMigrationIsVersionScoped(t *testing.T) {
242		t.Run("un doc ya migrado no se reescala, ni aplicándolo dos veces", func(t *testing.T) {
243			radius := 18.0
244			g := greeterElementWithRadius("shape", 220, 130, &radius)
245			g.SchemaVersion = SchemaVersionGreeterRadiusPercent // 13: ya en porcentaje
246	
247			NormalizeGreeter(&g)
248			NormalizeGreeter(&g)
249	
250			if got := g.Welcome.Image.Canvas.Elements[0].Radius; got == nil || *got != 18 {
251				t.Fatalf("radius = %v, want 18 (un porcentaje no se vuelve a reescalar)", got)
252			}
253		})
254	
255		t.Run("la versión ACTUAL del módulo tampoco lo reescala", func(t *testing.T) {
256			radius := 18.0
257			g := greeterElementWithRadius("shape", 220, 130, &radius)
258			g.SchemaVersion = SchemaVersionGreeter // 15: el caso que rompía
259	
260			NormalizeGreeter(&g)
261	
262			if got := g.Welcome.Image.Canvas.Elements[0].Radius; got == nil || *got != 18 {
263				t.Fatalf("radius = %v, want 18 — subir SchemaVersionGreeter volvió a disparar la migración", got)
264			}
265		})
266	
267		t.Run("un doc anterior a v13 sí se migra, una vez", func(t *testing.T) {
268			radius := 18.0
269			g := greeterElementWithRadius("shape", 220, 130, &radius)
270			g.SchemaVersion = SchemaVersionGreeterRadiusPercent - 1 // 12: píxeles
271	
272			// 18 px sobre la mitad del lado corto (130/2 = 65) ≈ 27.7 -> 28.
273			NormalizeGreeter(&g)
274			if got := g.Welcome.Image.Canvas.Elements[0].Radius; got == nil || *got != 28 {
275				t.Fatalf("radius = %v, want 28 (un doc legacy sí debe migrarse)", got)
276			}
277		})
278	}
279	
280	// TestNormalizeGreeter_LegacyDocDMImage 🛡️ — v14: un doc v13 nunca escribió
281	// `dm.image`, así que decodifica al valor cero de Go (igual que le pasaba al
282	// `image` de canal antes de existir el módulo): `mode: ""` y `elements: nil`.
283	// Sin este relleno, `mode` no casaría con ningún `DBGreeterImageMode` del
284	// dashboard y `elements: null` reventaría su `.map()` en cuanto alguien
285	// abriera el editor de imagen del privado por primera vez.
286	func TestNormalizeGreeter_LegacyDocDMImage(t *testing.T) {
287		g := legacyGreeter()
288		NormalizeGreeter(&g)
289	
290		if g.Welcome.DM.Image.Mode != GreeterImageBasic {
291			t.Fatalf("welcome.dm.image.mode = %q, want %q", g.Welcome.DM.Image.Mode, GreeterImageBasic)
292		}
293		if g.Welcome.DM.Image.Canvas.Elements == nil {
294			t.Fatal("welcome.dm.image.canvas.elements sigue nil (emitiría null en JSON)")
295		}
296	}
