298	// TestNormalizeGreeter_DMCanvasRadiusNotRescaled 🛡️ — v14: el reescalado de
299	// `radius` px->% (v13) NUNCA toca el canvas del privado, aunque
300	// normalizeGreeterMessageConfig acabe de normalizar sus huecos con la MISMA
301	// normalizeGreeterImage que usa el de canal. `DM.Image` nace en v14: ningún
302	// documento -ni siquiera uno v13, el escenario de este test- ha podido
303	// guardar ahí un `radius` en píxeles, así que no hay nada legacy que migrar.
304	// Pasarlo por la fórmula igualmente interpretaría como píxeles un porcentaje
305	// que el usuario podría escribir el mismo día que activa el bloque,
306	// corrompiéndolo en la primera lectura -exactamente el bug que evita el
307	// comentario "no lo arregles" en normalizeGreeterMessageConfig.
308	func TestNormalizeGreeter_DMCanvasRadiusNotRescaled(t *testing.T) {
309		g := ModuleGreeter{
310			SchemaVersion: 13,
311			Welcome: GreeterMessageConfig{
312				DM: GreeterDM{
313					Image: GreeterImage{
314						Canvas: GreeterImageCanvas{
315							Elements: []GreeterImageElement{
316								{ID: "e1", Type: "shape", Width: 220, Height: 130, Radius: radiusPtrForTest(40)},
317							},
318						},
319					},
320				},
321			},
322		}
323	
324		NormalizeGreeter(&g)
325	
326		got := g.Welcome.DM.Image.Canvas.Elements[0].Radius
327		if got == nil || *got != 40 {
328			t.Fatalf("dm.image.canvas radius = %v, want 40 (el canvas del privado no se reescala)", got)
329		}
330	}
331	
332	// TestNormalizeGreeter_DMCanvasSizeClamped 🛡️ — v14: el canvas del privado se
333	// acota EXACTAMENTE igual que el de canal, porque los dos pasan por la misma
334	// normalizeGreeterImage. Un `width`/`height` por encima de MaxCanvasSide -el
335	// mismo escenario de memoria nativa fuera de rango que documenta
336	// clampCanvasSide- no puede colarse por el bloque nuevo sólo porque sea
337	// nuevo; se comprueban canal y dm en el mismo documento para dejar
338	// constancia de que el tope es el mismo en los dos sitios.
339	func TestNormalizeGreeter_DMCanvasSizeClamped(t *testing.T) {
340		g := ModuleGreeter{
341			SchemaVersion: 9,
342			Welcome: GreeterMessageConfig{
343				Image: GreeterImage{
344					Canvas: GreeterImageCanvas{Width: 999999, Height: 999999},
345				},
346				DM: GreeterDM{
347					Image: GreeterImage{
348						Canvas: GreeterImageCanvas{Width: 999999, Height: 999999},
349					},
350				},
351			},
352		}
353	
354		NormalizeGreeter(&g)
355	
356		if g.Welcome.Image.Canvas.Width != MaxCanvasSide || g.Welcome.Image.Canvas.Height != MaxCanvasSide {
357			t.Fatalf("welcome.image.canvas = %dx%d, want %dx%d",
358				g.Welcome.Image.Canvas.Width, g.Welcome.Image.Canvas.Height, MaxCanvasSide, MaxCanvasSide)
359		}
360		if g.Welcome.DM.Image.Canvas.Width != MaxCanvasSide || g.Welcome.DM.Image.Canvas.Height != MaxCanvasSide {
361			t.Fatalf("welcome.dm.image.canvas = %dx%d, want %dx%d (debe acotarse igual que el de canal)",
362				g.Welcome.DM.Image.Canvas.Width, g.Welcome.DM.Image.Canvas.Height, MaxCanvasSide, MaxCanvasSide)
363		}
364	}
365	
366	// TestNormalizeGreeter_BoostReaction 🛡️ — v15: `boost_reaction` es aditivo y
367	// nace APAGADO (al revés que `dm_ack_reaction` de modmail), así que el
368	// bloque NO es puntero: el valor cero de un documento anterior al campo YA
369	// es el comportamiento previo (no reaccionar). Lo único que NormalizeGreeter
370	// tiene que reponer es el emoji en blanco -reaccionar con "" es un 400
371	// seguro de Discord-, sin tocar nunca `enabled`.
372	func TestNormalizeGreeter_BoostReaction(t *testing.T) {
373		t.Run("emoji vacío se repone al de fábrica", func(t *testing.T) {
374			g := legacyGreeter()
375			g.BoostReaction = GreeterBoostReaction{Enabled: true, Emoji: ""}
376			NormalizeGreeter(&g)
377			if g.BoostReaction.Emoji != GreeterDefaultBoostReactionEmoji {
378				t.Fatalf("boost_reaction.emoji = %q, want %q", g.BoostReaction.Emoji, GreeterDefaultBoostReactionEmoji)
379			}
380			if !g.BoostReaction.Enabled {
381				t.Fatal("enabled pisado por el backfill del emoji")
382			}
383		})
384	
385		t.Run("emoji sólo espacios también se repone", func(t *testing.T) {
386			g := legacyGreeter()
387			g.BoostReaction = GreeterBoostReaction{Enabled: false, Emoji: "   "}
388			NormalizeGreeter(&g)
389			if g.BoostReaction.Emoji != GreeterDefaultBoostReactionEmoji {
390				t.Fatalf("boost_reaction.emoji = %q, want %q", g.BoostReaction.Emoji, GreeterDefaultBoostReactionEmoji)
391			}
392		})
393	
394		// (b) el emoji que el usuario ya eligió NUNCA se pisa, ni aunque el
395		// bloque siga apagado -apagado no es "sin configurar".
396		t.Run("emoji del usuario no se pisa", func(t *testing.T) {
397			g := legacyGreeter()
398			g.BoostReaction = GreeterBoostReaction{Enabled: true, Emoji: "🔥"}
399			NormalizeGreeter(&g)
400			if g.BoostReaction.Emoji != "🔥" {
401				t.Fatalf("boost_reaction.emoji pisado: %q", g.BoostReaction.Emoji)
402			}
403			if !g.BoostReaction.Enabled {
404				t.Fatal("enabled pisado")
405			}
406		})
407	
408		// `Enabled` nace apagado y NormalizeGreeter jamás debe encenderlo solo
409		// -al revés que dm_ack_reaction de modmail, que nace encendido.
410		t.Run("enabled:false explícito no se enciende solo", func(t *testing.T) {
411			g := legacyGreeter()
412			g.BoostReaction = GreeterBoostReaction{Enabled: false, Emoji: "🎉"}
413			NormalizeGreeter(&g)
414			if g.BoostReaction.Enabled {
415				t.Fatal("boost_reaction se encendió solo")
416			}
417		})
418	
419		// (c) idempotencia: aplicar dos veces sobre un emoji ya repuesto no
420		// puede volver a tocar nada.
421		t.Run("idempotente", func(t *testing.T) {
422			g := legacyGreeter()
423			g.BoostReaction = GreeterBoostReaction{Enabled: true, Emoji: ""}
424			NormalizeGreeter(&g)
425			first, err := json.Marshal(g.BoostReaction)
426			if err != nil {
427				t.Fatalf("marshal: %v", err)
428			}
429			NormalizeGreeter(&g)
430			second, err := json.Marshal(g.BoostReaction)
431			if err != nil {
432				t.Fatalf("marshal: %v", err)
433			}
434			if string(first) != string(second) {
435				t.Fatalf("no idempotente:\n1: %s\n2: %s", first, second)
436			}
437		})
438	
439		// (d) un documento guardado antes de v15 nunca escribió la clave
440		// `boost_reaction`: construir el struct sin tocar el campo -mismo molde
441		// que legacyGreeter() usa para el resto del módulo- reproduce EXACTAMENTE
442		// lo que bson/json decodifican para una clave ausente, su valor cero.
443		t.Run("doc viejo sin el bloque decodifica apagado", func(t *testing.T) {
444			g := ModuleGreeter{SchemaVersion: 9}
445			if g.BoostReaction.Enabled {
446				t.Fatal("un doc sin el campo no puede decodificar encendido")
447			}
448			if g.BoostReaction.Emoji != "" {
449				t.Fatalf("un doc sin el campo no puede traer emoji: %q", g.BoostReaction.Emoji)
450			}
451	
452			NormalizeGreeter(&g)
453			if g.BoostReaction.Enabled {
454				t.Fatal("normalizar no puede encender boost_reaction solo")
455			}
456			if g.BoostReaction.Emoji != GreeterDefaultBoostReactionEmoji {
457				t.Fatalf("boost_reaction.emoji = %q tras normalizar, want %q", g.BoostReaction.Emoji, GreeterDefaultBoostReactionEmoji)
