package dbguild

import (
	"encoding/json"
	"math"
	"testing"
)

// TestNormalizeGreeter_NilReceiver — defensivo, igual que NormalizeTickets.
func TestNormalizeGreeter_NilReceiver(t *testing.T) {
	NormalizeGreeter(nil) // no debe entrar en pánico
}

// legacyGreeter reproduce lo que Mongo devuelve para un guild v9/v10: bloques
// que existen pero nunca se escribieron enteros, así que decodifican al valor
// cero de Go — enums vacíos, slices nil y un lienzo 0x0.
func legacyGreeter() ModuleGreeter {
	return ModuleGreeter{
		SchemaVersion: 9,
		Enabled:       true,
		Welcome: GreeterMessageConfig{
			Enabled: true,
			Message: GreeterMessage{Content: "¡Hola {user}!"},
		},
	}
}

// TestNormalizeGreeter_LegacyDoc 🛡️ — un doc legacy sale del normalizador con
// la forma que el dashboard y el bot esperan. Sin esto: `mode: ""` no casa con
// ningún modo del renderer (el bot no publica nada mientras el dashboard lo
// pinta como `plain`), y `elements: null` revienta el `.map()` del dashboard y
// el `for..of` del bot.
func TestNormalizeGreeter_LegacyDoc(t *testing.T) {
	g := legacyGreeter()
	NormalizeGreeter(&g)

	if g.Welcome.Message.Mode != GreeterModePlain {
		t.Fatalf("welcome.message.mode = %q, want %q", g.Welcome.Message.Mode, GreeterModePlain)
	}
	if g.Welcome.DM.Message.Mode != GreeterModePlain {
		t.Fatalf("welcome.dm.message.mode = %q, want %q", g.Welcome.DM.Message.Mode, GreeterModePlain)
	}
	if g.Welcome.Image.Mode != GreeterImageBasic {
		t.Fatalf("welcome.image.mode = %q, want %q", g.Welcome.Image.Mode, GreeterImageBasic)
	}
	if g.Welcome.Image.Canvas.Elements == nil {
		t.Fatal("welcome.image.canvas.elements sigue nil (emitiría null en JSON)")
	}
	if g.Welcome.Image.Canvas.Width != 1024 || g.Welcome.Image.Canvas.Height != 500 {
		t.Fatalf("canvas = %dx%d, want 1024x500", g.Welcome.Image.Canvas.Width, g.Welcome.Image.Canvas.Height)
	}
	if g.JoinRoles.RolesID == nil {
		t.Fatal("join_roles.roles_id sigue nil")
	}
	if len(g.Variables.Allowed) != len(DefaultGreeterVariables()) {
		t.Fatalf("variables.allowed = %v, want los %d por defecto", g.Variables.Allowed, len(DefaultGreeterVariables()))
	}
	// Goodbye y boost reciben el mismo trato.
	if g.Goodbye.Message.Mode != GreeterModePlain || g.Boost.Message.Mode != GreeterModePlain {
		t.Fatalf("goodbye/boost mode = %q/%q, want plain", g.Goodbye.Message.Mode, g.Boost.Message.Mode)
	}
}

// TestNormalizeGreeter_NoClobber 🛡️ — normalizar NO puede pisar configuración
// existente. Es la diferencia entre migrar un doc legacy y resetearlo: para un
// v9 con ajustes reales, sustituirlo por los defaults borraría el trabajo del
// usuario.
func TestNormalizeGreeter_NoClobber(t *testing.T) {
	g := legacyGreeter()
	g.Welcome.Message.Mode = GreeterModeEmbedImage
	g.Welcome.Image.Mode = GreeterImageAdvanced
	g.Welcome.Image.Canvas.Width = 640
	g.Welcome.Image.Canvas.Height = 360
	g.Welcome.Image.Canvas.Elements = []GreeterImageElement{{ID: "e1", Type: "text"}}
	g.JoinRoles.RolesID = []string{"role1"}
	g.Variables.Allowed = []string{"user"}

	NormalizeGreeter(&g)

	if g.Welcome.Message.Mode != GreeterModeEmbedImage {
		t.Fatalf("mode pisado: %q", g.Welcome.Message.Mode)
	}
	if g.Welcome.Image.Mode != GreeterImageAdvanced {
		t.Fatalf("image.mode pisado: %q", g.Welcome.Image.Mode)
	}
	if g.Welcome.Image.Canvas.Width != 640 || g.Welcome.Image.Canvas.Height != 360 {
		t.Fatalf("canvas pisado: %dx%d", g.Welcome.Image.Canvas.Width, g.Welcome.Image.Canvas.Height)
	}
	if len(g.Welcome.Image.Canvas.Elements) != 1 || g.Welcome.Image.Canvas.Elements[0].ID != "e1" {
		t.Fatalf("elements pisados: %v", g.Welcome.Image.Canvas.Elements)
	}
	if len(g.JoinRoles.RolesID) != 1 || g.JoinRoles.RolesID[0] != "role1" {
		t.Fatalf("roles_id pisados: %v", g.JoinRoles.RolesID)
	}
	if len(g.Variables.Allowed) != 1 {
		t.Fatalf("variables.allowed pisadas: %v", g.Variables.Allowed)
	}
	// Y el contenido del mensaje, que es lo que de verdad duele perder.
	if g.Welcome.Message.Content != "¡Hola {user}!" {
		t.Fatalf("content pisado: %q", g.Welcome.Message.Content)
	}
}

// TestNormalizeGreeter_Idempotent — aplicarlo dos veces da el mismo resultado.
func TestNormalizeGreeter_Idempotent(t *testing.T) {
	g := legacyGreeter()
	NormalizeGreeter(&g)
	first, err := json.Marshal(g)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	NormalizeGreeter(&g)
	second, err := json.Marshal(g)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if string(first) != string(second) {
		t.Fatalf("no idempotente:\n1: %s\n2: %s", first, second)
	}
}

// TestModuleGreeter_CaptchaEmitsNull 🛡️ — `captcha` nulo tiene que salir como
// `null`, NO desaparecer del JSON. La regla del fichero es que la salida
// conserve la forma del tipo TS: con `omitempty` en el tag json, un consumidor
// que leyera `data.captcha.enabled` recibía `undefined` en vez de `null` y
// petaba con un TypeError. `captcha` era el único nullable del greeter con
// omitempty en json; el resto (`enabled_since`, `channel_id`…) ya emitían null.
func TestModuleGreeter_CaptchaEmitsNull(t *testing.T) {
	var g ModuleGreeter
	g.Captcha = nil

	b, err := json.Marshal(g)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}

	var raw map[string]json.RawMessage
	if err := json.Unmarshal(b, &raw); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	v, ok := raw["captcha"]
	if !ok {
		t.Fatalf("la clave `captcha` no aparece en el JSON: %s", b)
	}
	if string(v) != "null" {
		t.Fatalf("captcha = %s, want null", v)
	}
}

// radiusPtrForTest fabrica un *float64 para poblar `Radius` en los tests de
// migración — mismo molde que boolPtrForTest en module_modmail_test.go.
func radiusPtrForTest(v float64) *float64 { return &v }

// greeterElementWithRadius monta el ModuleGreeter mínimo que
// normalizeGreeterMessageConfig necesita para reescalar UN elemento del
// canvas de welcome: SchemaVersion legacy (cualquier valor por debajo de
// SchemaVersionGreeter sirve; NormalizeGreeter no la mira) y un único
// elemento con su PROPIA caja `width`x`height` -la que manda según el
// contrato, no la del canvas-.
func greeterElementWithRadius(elemType string, width, height float64, radius *float64) ModuleGreeter {
	return ModuleGreeter{
		SchemaVersion: 9,
		Welcome: GreeterMessageConfig{
			Image: GreeterImage{
				Canvas: GreeterImageCanvas{
					Elements: []GreeterImageElement{
						{ID: "e1", Type: elemType, Width: width, Height: height, Radius: radius},
					},
				},
			},
		},
	}
}

// TestNormalizeGreeter_RadiusPxToPercent 🛡️ — v13: el mismo número de
// `radius` pasa a significar otra cosa (porcentaje del lado corto DEL
// ELEMENTO, no del canvas, en vez de píxeles), así que NormalizeGreeter tiene
// que reescalar cada valor YA guardado con la fórmula del contrato
// (`pct = round(clamp(px / (min(w,h)/2) * 100, 0, 100))`) en vez de
// limitarse a rellenar huecos. Cubre: el sentinela viejo de "redondo del
// todo" (9999px, el que usaban avatares/círculos), un valor intermedio real,
// el cero, la ausencia de valor (no se inventa un dato que el usuario nunca
// puso) y una caja degenerada (ancho o alto 0) que no debe dar +Inf/NaN.
func TestNormalizeGreeter_RadiusPxToPercent(t *testing.T) {
	cases := []struct {
		name          string
		elemType      string
		width, height float64
		radius        *float64
		want          *float64
	}{
		// (a) avatar 200x200 con el sentinela viejo 9999px -> clamp a 100.
		{"sentinel avatar 9999px", "avatar", 200, 200, radiusPtrForTest(9999), radiusPtrForTest(100)},
		// (b) figura 220x130 con 12px -> 12 / 65 * 100 = 18.46... -> 18.
		{"figura 220x130 con 12px", "shape", 220, 130, radiusPtrForTest(12), radiusPtrForTest(18)},
		// (c) 0px sigue 0.
		{"cero sigue cero", "image", 200, 200, radiusPtrForTest(0), radiusPtrForTest(0)},
		// (d) nil no se inventa un valor.
		{"nil no se inventa", "image", 200, 200, nil, nil},
		// (e) caja degenerada (ancho 0) -> 0, nunca +Inf/NaN.
		{"ancho cero", "shape", 0, 130, radiusPtrForTest(12), radiusPtrForTest(0)},
		// (e) caja degenerada (alto 0) -> 0.
		{"alto cero", "shape", 220, 0, radiusPtrForTest(12), radiusPtrForTest(0)},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			g := greeterElementWithRadius(c.elemType, c.width, c.height, c.radius)
			NormalizeGreeter(&g)

			got := g.Welcome.Image.Canvas.Elements[0].Radius
			if c.want == nil {
				if got != nil {
					t.Fatalf("radius = %v, want nil", *got)
				}
				return
			}
			if got == nil {
				t.Fatalf("radius = nil, want %v", *c.want)
			}
			if *got != *c.want {
				t.Fatalf("radius = %v, want %v", *got, *c.want)
			}
			// El resultado tiene que ser siempre finito -las cajas
			// degeneradas de arriba no pueden colarse como +Inf/NaN.
			if math.IsNaN(*got) || math.IsInf(*got, 0) {
				t.Fatalf("radius = %v no es finito", *got)
			}
		})
	}
}

// TestNormalizeGreeter_RadiusMigrationIsVersionScoped 🛡️ — el guard de versión
// vive DENTRO de NormalizeGreeter y mira la versión del DOCUMENTO
// (`SchemaVersionGreeterRadiusPercent`), no la del código.
//
// Antes lo ponía el llamador con `SchemaVersion < SchemaVersionGreeter`, y eso
// protegió exactamente mientras la constante valió 13: al subirla a 14 y a 15,
// un documento ya migrado volvía a colarse por ese guard y se reescalaba una
// segunda vez. Este test fija que el reescalado depende de dónde está el
// documento, y que aplicarlo dos veces ya no puede deformar nada.
func TestNormalizeGreeter_RadiusMigrationIsVersionScoped(t *testing.T) {
	t.Run("un doc ya migrado no se reescala, ni aplicándolo dos veces", func(t *testing.T) {
		radius := 18.0
		g := greeterElementWithRadius("shape", 220, 130, &radius)
		g.SchemaVersion = SchemaVersionGreeterRadiusPercent // 13: ya en porcentaje

		NormalizeGreeter(&g)
		NormalizeGreeter(&g)

		if got := g.Welcome.Image.Canvas.Elements[0].Radius; got == nil || *got != 18 {
			t.Fatalf("radius = %v, want 18 (un porcentaje no se vuelve a reescalar)", got)
		}
	})

	t.Run("la versión ACTUAL del módulo tampoco lo reescala", func(t *testing.T) {
		radius := 18.0
		g := greeterElementWithRadius("shape", 220, 130, &radius)
		g.SchemaVersion = SchemaVersionGreeter // 15: el caso que rompía

		NormalizeGreeter(&g)

		if got := g.Welcome.Image.Canvas.Elements[0].Radius; got == nil || *got != 18 {
			t.Fatalf("radius = %v, want 18 — subir SchemaVersionGreeter volvió a disparar la migración", got)
		}
	})

	t.Run("un doc anterior a v13 sí se migra, una vez", func(t *testing.T) {
		radius := 18.0
		g := greeterElementWithRadius("shape", 220, 130, &radius)
		g.SchemaVersion = SchemaVersionGreeterRadiusPercent - 1 // 12: píxeles

		// 18 px sobre la mitad del lado corto (130/2 = 65) ≈ 27.7 -> 28.
		NormalizeGreeter(&g)
		if got := g.Welcome.Image.Canvas.Elements[0].Radius; got == nil || *got != 28 {
			t.Fatalf("radius = %v, want 28 (un doc legacy sí debe migrarse)", got)
		}
	})
}

// TestNormalizeGreeter_LegacyDocDMImage 🛡️ — v14: un doc v13 nunca escribió
// `dm.image`, así que decodifica al valor cero de Go (igual que le pasaba al
// `image` de canal antes de existir el módulo): `mode: ""` y `elements: nil`.
// Sin este relleno, `mode` no casaría con ningún `DBGreeterImageMode` del
// dashboard y `elements: null` reventaría su `.map()` en cuanto alguien
// abriera el editor de imagen del privado por primera vez.
func TestNormalizeGreeter_LegacyDocDMImage(t *testing.T) {
	g := legacyGreeter()
	NormalizeGreeter(&g)

	if g.Welcome.DM.Image.Mode != GreeterImageBasic {
		t.Fatalf("welcome.dm.image.mode = %q, want %q", g.Welcome.DM.Image.Mode, GreeterImageBasic)
	}
	if g.Welcome.DM.Image.Canvas.Elements == nil {
		t.Fatal("welcome.dm.image.canvas.elements sigue nil (emitiría null en JSON)")
	}
}

// TestNormalizeGreeter_DMCanvasRadiusNotRescaled 🛡️ — v14: el reescalado de
// `radius` px->% (v13) NUNCA toca el canvas del privado, aunque
// normalizeGreeterMessageConfig acabe de normalizar sus huecos con la MISMA
// normalizeGreeterImage que usa el de canal. `DM.Image` nace en v14: ningún
// documento -ni siquiera uno v13, el escenario de este test- ha podido
// guardar ahí un `radius` en píxeles, así que no hay nada legacy que migrar.
// Pasarlo por la fórmula igualmente interpretaría como píxeles un porcentaje
// que el usuario podría escribir el mismo día que activa el bloque,
// corrompiéndolo en la primera lectura -exactamente el bug que evita el
// comentario "no lo arregles" en normalizeGreeterMessageConfig.
func TestNormalizeGreeter_DMCanvasRadiusNotRescaled(t *testing.T) {
	g := ModuleGreeter{
		SchemaVersion: 13,
		Welcome: GreeterMessageConfig{
			DM: GreeterDM{
				Image: GreeterImage{
					Canvas: GreeterImageCanvas{
						Elements: []GreeterImageElement{
							{ID: "e1", Type: "shape", Width: 220, Height: 130, Radius: radiusPtrForTest(40)},
						},
					},
				},
			},
		},
	}

	NormalizeGreeter(&g)

	got := g.Welcome.DM.Image.Canvas.Elements[0].Radius
	if got == nil || *got != 40 {
		t.Fatalf("dm.image.canvas radius = %v, want 40 (el canvas del privado no se reescala)", got)
	}
}

// TestNormalizeGreeter_DMCanvasSizeClamped 🛡️ — v14: el canvas del privado se
// acota EXACTAMENTE igual que el de canal, porque los dos pasan por la misma
// normalizeGreeterImage. Un `width`/`height` por encima de MaxCanvasSide -el
// mismo escenario de memoria nativa fuera de rango que documenta
// clampCanvasSide- no puede colarse por el bloque nuevo sólo porque sea
// nuevo; se comprueban canal y dm en el mismo documento para dejar
// constancia de que el tope es el mismo en los dos sitios.
func TestNormalizeGreeter_DMCanvasSizeClamped(t *testing.T) {
	g := ModuleGreeter{
		SchemaVersion: 9,
		Welcome: GreeterMessageConfig{
			Image: GreeterImage{
				Canvas: GreeterImageCanvas{Width: 999999, Height: 999999},
			},
			DM: GreeterDM{
				Image: GreeterImage{
					Canvas: GreeterImageCanvas{Width: 999999, Height: 999999},
				},
			},
		},
	}

	NormalizeGreeter(&g)

	if g.Welcome.Image.Canvas.Width != MaxCanvasSide || g.Welcome.Image.Canvas.Height != MaxCanvasSide {
		t.Fatalf("welcome.image.canvas = %dx%d, want %dx%d",
			g.Welcome.Image.Canvas.Width, g.Welcome.Image.Canvas.Height, MaxCanvasSide, MaxCanvasSide)
	}
	if g.Welcome.DM.Image.Canvas.Width != MaxCanvasSide || g.Welcome.DM.Image.Canvas.Height != MaxCanvasSide {
		t.Fatalf("welcome.dm.image.canvas = %dx%d, want %dx%d (debe acotarse igual que el de canal)",
			g.Welcome.DM.Image.Canvas.Width, g.Welcome.DM.Image.Canvas.Height, MaxCanvasSide, MaxCanvasSide)
	}
}

// TestNormalizeGreeter_BoostReaction 🛡️ — v15: `boost_reaction` es aditivo y
// nace APAGADO (al revés que `dm_ack_reaction` de modmail), así que el
// bloque NO es puntero: el valor cero de un documento anterior al campo YA
// es el comportamiento previo (no reaccionar). Lo único que NormalizeGreeter
// tiene que reponer es el emoji en blanco -reaccionar con "" es un 400
// seguro de Discord-, sin tocar nunca `enabled`.
func TestNormalizeGreeter_BoostReaction(t *testing.T) {
	t.Run("emoji vacío se repone al de fábrica", func(t *testing.T) {
		g := legacyGreeter()
		g.BoostReaction = GreeterBoostReaction{Enabled: true, Emoji: ""}
		NormalizeGreeter(&g)
		if g.BoostReaction.Emoji != GreeterDefaultBoostReactionEmoji {
			t.Fatalf("boost_reaction.emoji = %q, want %q", g.BoostReaction.Emoji, GreeterDefaultBoostReactionEmoji)
		}
		if !g.BoostReaction.Enabled {
			t.Fatal("enabled pisado por el backfill del emoji")
		}
	})

	t.Run("emoji sólo espacios también se repone", func(t *testing.T) {
		g := legacyGreeter()
		g.BoostReaction = GreeterBoostReaction{Enabled: false, Emoji: "   "}
		NormalizeGreeter(&g)
		if g.BoostReaction.Emoji != GreeterDefaultBoostReactionEmoji {
			t.Fatalf("boost_reaction.emoji = %q, want %q", g.BoostReaction.Emoji, GreeterDefaultBoostReactionEmoji)
		}
	})

	// (b) el emoji que el usuario ya eligió NUNCA se pisa, ni aunque el
	// bloque siga apagado -apagado no es "sin configurar".
	t.Run("emoji del usuario no se pisa", func(t *testing.T) {
		g := legacyGreeter()
		g.BoostReaction = GreeterBoostReaction{Enabled: true, Emoji: "🔥"}
		NormalizeGreeter(&g)
		if g.BoostReaction.Emoji != "🔥" {
			t.Fatalf("boost_reaction.emoji pisado: %q", g.BoostReaction.Emoji)
		}
		if !g.BoostReaction.Enabled {
			t.Fatal("enabled pisado")
		}
	})

	// `Enabled` nace apagado y NormalizeGreeter jamás debe encenderlo solo
	// -al revés que dm_ack_reaction de modmail, que nace encendido.
	t.Run("enabled:false explícito no se enciende solo", func(t *testing.T) {
		g := legacyGreeter()
		g.BoostReaction = GreeterBoostReaction{Enabled: false, Emoji: "🎉"}
		NormalizeGreeter(&g)
		if g.BoostReaction.Enabled {
			t.Fatal("boost_reaction se encendió solo")
		}
	})

	// (c) idempotencia: aplicar dos veces sobre un emoji ya repuesto no
	// puede volver a tocar nada.
	t.Run("idempotente", func(t *testing.T) {
		g := legacyGreeter()
		g.BoostReaction = GreeterBoostReaction{Enabled: true, Emoji: ""}
		NormalizeGreeter(&g)
		first, err := json.Marshal(g.BoostReaction)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		NormalizeGreeter(&g)
		second, err := json.Marshal(g.BoostReaction)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		if string(first) != string(second) {
			t.Fatalf("no idempotente:\n1: %s\n2: %s", first, second)
		}
	})

	// (d) un documento guardado antes de v15 nunca escribió la clave
	// `boost_reaction`: construir el struct sin tocar el campo -mismo molde
	// que legacyGreeter() usa para el resto del módulo- reproduce EXACTAMENTE
	// lo que bson/json decodifican para una clave ausente, su valor cero.
	t.Run("doc viejo sin el bloque decodifica apagado", func(t *testing.T) {
		g := ModuleGreeter{SchemaVersion: 9}
		if g.BoostReaction.Enabled {
			t.Fatal("un doc sin el campo no puede decodificar encendido")
		}
		if g.BoostReaction.Emoji != "" {
			t.Fatalf("un doc sin el campo no puede traer emoji: %q", g.BoostReaction.Emoji)
		}

		NormalizeGreeter(&g)
		if g.BoostReaction.Enabled {
			t.Fatal("normalizar no puede encender boost_reaction solo")
		}
		if g.BoostReaction.Emoji != GreeterDefaultBoostReactionEmoji {
			t.Fatalf("boost_reaction.emoji = %q tras normalizar, want %q", g.BoostReaction.Emoji, GreeterDefaultBoostReactionEmoji)
		}
	})
}

