37	var infractionTypeSet = map[string]bool{
38		dbinfraction.TypeWarn: true, dbinfraction.TypeNote: true, dbinfraction.TypeMute: true,
39		dbinfraction.TypeTempmute: true, dbinfraction.TypeUnmute: true, dbinfraction.TypeKick: true,
40		dbinfraction.TypeBan: true, dbinfraction.TypeTempban: true, dbinfraction.TypeUnban: true,
41		dbinfraction.TypeBlind: true,
42	}
43	
44	var infractionStatusSet = map[string]bool{
45		dbinfraction.StatusActive: true, dbinfraction.StatusPending: true,
46		dbinfraction.StatusExpired: true, dbinfraction.StatusRevoked: true,
47	}
48	
49	// infractionSourceSet incluye `system` (migración 025): es el origen que estampan
50	// los automatismos del módulo (escalado, anti-raid, filtro de entrada, anti-nuke).
51	// Vale tanto para el POST de creación como para el filtro `?source=` del listado —
52	// ambos comparten este set.
53	var infractionSourceSet = map[string]bool{
54		dbinfraction.SourceManual: true, dbinfraction.SourceAutomod: true,
55		dbinfraction.SourceAPI: true, dbinfraction.SourceDiscord: true,
56		dbinfraction.SourceSystem: true,
57	}
