64		infractionTypeMsg      = `Invalid option: expected one of "warn"|"note"|"mute"|"tempmute"|"unmute"|"kick"|"ban"|"tempban"|"unban"|"blind"`
65		infractionStatusMsg    = `Invalid option: expected one of "active"|"pending"|"expired"|"revoked"`
66		infractionSourceMsg    = `Invalid option: expected one of "manual"|"automod"|"api"|"discord"|"system"`
67		infractionMechanismMsg = `Invalid option: expected one of "timeout"|"role"`
68	)
