82	// moderator_id, moderator_label, status, source, source_detail, reason, mechanism,
83	// duration_ms, expires_at, applied_at, rule_id, channel_id, message_id, metadata.
84	// `snowflake` = z.string().min(1).max(32); `label` = z.string().max(128).nullable.
85	func ParseInfractionCreate(body []byte) (dbinfraction.CreateData, *apierrors.CustomError) {
86		var raw struct {
87			BotID          json.RawMessage `json:"bot_id"`
88			GuildID        json.RawMessage `json:"guild_id"`
89			UserID         json.RawMessage `json:"user_id"`
90			Type           json.RawMessage `json:"type"`
