96			SourceDetail   json.RawMessage `json:"source_detail"`
97			Reason         json.RawMessage `json:"reason"`
98			Mechanism      json.RawMessage `json:"mechanism"`
99			DurationMs     json.RawMessage `json:"duration_ms"`
100			ExpiresAt      json.RawMessage `json:"expires_at"`
101			AppliedAt      json.RawMessage `json:"applied_at"`
102			RuleID         json.RawMessage `json:"rule_id"`
103			ChannelID      json.RawMessage `json:"channel_id"`
104			MessageID      json.RawMessage `json:"message_id"`
