119			return d, verr
120		}
121		if d.Type, verr = parseEnumRequired(raw.Type, infractionTypeSet, infractionTypeMsg, "type"); verr != nil {
122			return d, verr
123		}
124		if d.UserLabel, verr = parseNullableBoundedString(raw.UserLabel, "user_label", 0, 128); verr != nil {
125			return d, verr
126		}
127		if d.ModeratorID, verr = parseNullableBoundedString(raw.ModeratorID, "moderator_id", 1, 32); verr != nil {
128			return d, verr
129		}
130		if d.ModeratorLabel, verr = parseNullableBoundedString(raw.ModeratorLabel, "moderator_label", 0, 128); verr != nil {
131			return d, verr
132		}
133		if d.Status, verr = parseOptionalEnum(raw.Status, infractionStatusSet, infractionStatusMsg, "status"); verr != nil {
134			return d, verr
