145		if d.Mechanism, verr = parseNullableEnum(raw.Mechanism, infractionMechanismSet, infractionMechanismMsg, "mechanism"); verr != nil {
146			return d, verr
147		}
148		if d.DurationMs, verr = parseNullableInt64NonNeg(raw.DurationMs, "duration_ms"); verr != nil {
149			return d, verr
