172	// ─── GET / (list) ─────────────────────────────────────────────────────────
173	
174	// ParseInfractionListQuery mirrors `infractionListQuery`. Shape order: limit,
175	// offset, bot_id, guild_id, user_id, moderator_id, type, status, source,
176	// case_number, expires_before, created_after, types, statuses. limit
177	// `.min(1).max(200)` (reuses coerceTrackErrorLimit); case_number
178	// `z.coerce.number().int().positive()` (reuses coercePositive); expires_before y
179	// created_after `z.string().datetime({ offset: true })`.
180	// An EMPTY query string is treated as ABSENT.
181	//
182	// `types` y `statuses` son listas CSV (`warn,mute`) que CONVIVEN con los filtros
183	// singulares `type` / `status`: si llegan los dos, se acumulan en el WHERE con
184	// AND. Cada elemento se valida contra el MISMO set que el singular y falla con el
185	// mismo mensaje de enum. `created_after` es lo que necesita el escalado automático
186	// para acotar su ventana de conteo.
187	func ParseInfractionListQuery(limitRaw, offsetRaw, botID, guildID, userID, moderatorID, typ, status, source, caseNumberRaw, expiresBefore, createdAfter, typesRaw, statusesRaw string) (dbinfraction.ListParams, *apierrors.CustomError) {
188		var p dbinfraction.ListParams
189		limitPtr, verr := coerceTrackErrorLimit(limitRaw)
190		if verr != nil {
191			return p, verr
192		}
193		p.Limit = limitPtr
194		offsetPtr, verr := coerceOffset(offsetRaw)
195		if verr != nil {
196			return p, verr
197		}
198		p.Offset = offsetPtr
199		if botID != "" {
200			v := botID
201			p.BotID = &v
202		}
203		if guildID != "" {
204			v := guildID
205			p.GuildID = &v
206		}
207		if userID != "" {
208			v := userID
209			p.UserID = &v
210		}
211		if moderatorID != "" {
212			v := moderatorID
213			p.ModeratorID = &v
214		}
215		if typ != "" {
216			if !infractionTypeSet[typ] {
217				return p, zodItemError(infractionTypeMsg, "type")
218			}
219			v := typ
220			p.Type = &v
221		}
222		if status != "" {
223			if !infractionStatusSet[status] {
224				return p, zodItemError(infractionStatusMsg, "status")
225			}
226			v := status
227			p.Status = &v
228		}
229		if source != "" {
230			if !infractionSourceSet[source] {
231				return p, zodItemError(infractionSourceMsg, "source")
232			}
233			v := source
234			p.Source = &v
235		}
236		caseNumberPtr, verr := coercePositive(caseNumberRaw, "case_number")
237		if verr != nil {
238			return p, verr
239		}
240		p.CaseNumber = caseNumberPtr
241		if expiresBefore != "" {
242			if !infractionOffsetDateTimeRe.MatchString(expiresBefore) {
243				return p, zodItemError("Invalid ISO datetime", "expires_before")
244			}
245			v := expiresBefore
246			p.ExpiresBefore = &v
247		}
248		// created_after: mismo formato y misma regex que expires_before.
249		if createdAfter != "" {
250			if !infractionOffsetDateTimeRe.MatchString(createdAfter) {
251				return p, zodItemError("Invalid ISO datetime", "created_after")
252			}
253			v := createdAfter
254			p.CreatedAfter = &v
255		}
256		types, verr := parseInfractionEnumCSV(typesRaw, infractionTypeSet, infractionTypeMsg, "types")
257		if verr != nil {
258			return p, verr
259		}
260		p.Types = types
261		statuses, verr := parseInfractionEnumCSV(statusesRaw, infractionStatusSet, infractionStatusMsg, "statuses")
262		if verr != nil {
263			return p, verr
264		}
265		p.Statuses = statuses
266		return p, nil
267	}
268	
269	// parseInfractionEnumCSV convierte un filtro CSV (`warn,mute`) en la lista de
270	// valores validados contra `set`. Los elementos vacíos se IGNORAN (`warn,,mute` y
271	// `warn, mute` dan ambos ["warn","mute"]), y un CSV entero vacío —o que sólo
272	// tenga separadores— devuelve nil, es decir, filtro AUSENTE. El primer elemento
273	// que no esté en el set corta con el MISMO mensaje de enum que el filtro singular
274	// equivalente, sólo que con la propiedad en plural.
275	func parseInfractionEnumCSV(raw string, set map[string]bool, msg, property string) ([]string, *apierrors.CustomError) {
276		if raw == "" {
277			return nil, nil
278		}
279		out := []string{}
280		for _, part := range strings.Split(raw, ",") {
281			v := strings.TrimSpace(part)
282			if v == "" {
283				continue
284			}
285			if !set[v] {
286				return nil, zodItemError(msg, property)
287			}
288			out = append(out, v)
289		}
290		if len(out) == 0 {
291			return nil, nil
292		}
293		return out, nil
294	}
295	
296	// ─── DELETE / (bulk delete-by-user) ───────────────────────────────────────
297	
298	// ParseInfractionDeleteByUser mirrors `infractionDeleteByUserQuery`
299	// (`{ bot_id: z.string().min(1), guild_id: z.string().min(1),
300	// user_id: z.string().min(1) }` — all required). Shape order: bot_id, guild_id,
301	// user_id. Backs the `delinfs` bulk delete.
302	func ParseInfractionDeleteByUser(botID, guildID, userID string) (string, string, string, *apierrors.CustomError) {
303		if verr := validateStringLen(botID, "bot_id", 1, 0); verr != nil {
304			return "", "", "", verr
305		}
306		if verr := validateStringLen(guildID, "guild_id", 1, 0); verr != nil {
307			return "", "", "", verr
308		}
309		if verr := validateStringLen(userID, "user_id", 1, 0); verr != nil {
310			return "", "", "", verr
311		}
312		return botID, guildID, userID, nil
313	}
314	
315	// ─── path params ──────────────────────────────────────────────────────────
316	
317	// ParseInfractionIDParam mirrors `infractionIdParams.id`
318	// (z.coerce.number().int().positive(), property "id"). Identical schema to the
319	// tracks db-id param, so it delegates.
320	func ParseInfractionIDParam(raw string) (int64, *apierrors.CustomError) {
321		return ParseTrackDBIDParam(raw)
322	}
323	
324	// ─── PATCH /:id (update) ──────────────────────────────────────────────────
325	
326	// ParseInfractionUpdate mirrors `infractionUpdateBody` (NOT strict; every field
327	// optional). Builds the present-columns map (a present null → a nil map value →
328	// SQL NULL). An empty body yields an empty map; the repo turns that into
329	// `findById(id)`, matching Node's `if sets.length === 0 return findById(id)`.
330	// Fields validate in zod declaration order: reason, duration_ms, expires_at,
331	// status, mechanism, applied_at, revoked_at, revoked_by, revoke_reason.
332	func ParseInfractionUpdate(body []byte) (map[string]any, *apierrors.CustomError) {
333		var raw struct {
334			Reason       json.RawMessage `json:"reason"`
335			DurationMs   json.RawMessage `json:"duration_ms"`
336			ExpiresAt    json.RawMessage `json:"expires_at"`
337			Status       json.RawMessage `json:"status"`
338			Mechanism    json.RawMessage `json:"mechanism"`
339			AppliedAt    json.RawMessage `json:"applied_at"`
340			RevokedAt    json.RawMessage `json:"revoked_at"`
341			RevokedBy    json.RawMessage `json:"revoked_by"`
342			RevokeReason json.RawMessage `json:"revoke_reason"`
343		}
344		if err := json.Unmarshal(body, &raw); err != nil {
345			return nil, bodyBindError(err)
346		}
347		set := map[string]any{}
348		// reason: z.string().max(2000).nullable().optional().
349		if verr := addMetaStringField(set, "reason", raw.Reason, "reason", 2000, false); verr != nil {
350			return nil, verr
351		}
352		// duration_ms: z.number().int().nonnegative().nullable().optional().
353		if verr := addNullableIntField(set, "duration_ms", raw.DurationMs, "duration_ms", 0, 0); verr != nil {
354			return nil, verr
355		}
356		// expires_at: z.string().datetime({ offset: true }).nullable().optional().
357		if verr := addNullableOffsetDatetimeField(set, "expires_at", raw.ExpiresAt, "expires_at"); verr != nil {
358			return nil, verr
359		}
360		// status: z.enum(statusValues).optional() (NOT nullable → present null is an enum error).
361		if verr := addOptionalEnumField(set, "status", raw.Status, infractionStatusSet, infractionStatusMsg, "status"); verr != nil {
362			return nil, verr
363		}
364		// mechanism: z.enum(mechanismValues).nullable().optional().
365		if verr := addNullableEnumField(set, "mechanism", raw.Mechanism, infractionMechanismSet, infractionMechanismMsg, "mechanism"); verr != nil {
366			return nil, verr
367		}
368		// applied_at / revoked_at: z.string().datetime({ offset: true }).nullable().optional().
369		if verr := addNullableOffsetDatetimeField(set, "applied_at", raw.AppliedAt, "applied_at"); verr != nil {
370			return nil, verr
371		}
372		if verr := addNullableOffsetDatetimeField(set, "revoked_at", raw.RevokedAt, "revoked_at"); verr != nil {
373			return nil, verr
374		}
375		// revoked_by: z.string().max(32).nullable().optional().
376		if verr := addMetaStringField(set, "revoked_by", raw.RevokedBy, "revoked_by", 32, false); verr != nil {
377			return nil, verr
378		}
379		// revoke_reason: z.string().max(2000).nullable().optional().
380		if verr := addMetaStringField(set, "revoke_reason", raw.RevokeReason, "revoke_reason", 2000, false); verr != nil {
381			return nil, verr
382		}
383		return set, nil
384	}
385	
386	// ─── field helpers (moderation-specific) ──────────────────────────────────
387	
388	// parseNullableBoundedString mirrors an OPTIONAL, NULLABLE `z.string()[.min][.max]`
389	// field returning a pointer: absent OR present null → nil (→ the repo binds SQL
390	// NULL, since absent and null both feed the Node repo's `?? null`); wrong type →
391	// "received X"; then the length bounds; else the value. A minLen/maxLen of 0
392	// disables that bound.
393	func parseNullableBoundedString(raw json.RawMessage, property string, minLen, maxLen int) (*string, *apierrors.CustomError) {
394		if raw == nil || isJSONNull(raw) {
395			return nil, nil
396		}
397		var s string
398		if err := json.Unmarshal(raw, &s); err != nil {
399			return nil, zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
400		}
401		if verr := validateStringLen(s, property, minLen, maxLen); verr != nil {
402			return nil, verr
403		}
404		return &s, nil
405	}
406	
407	// parseOptionalEnum mirrors an OPTIONAL, non-nullable `z.enum(values)` field
408	// returning a pointer: absent → nil; a listed string → the value; anything else
409	// (including a present null) → the enum message.
410	func parseOptionalEnum(raw json.RawMessage, values map[string]bool, msg, property string) (*string, *apierrors.CustomError) {
411		if raw == nil {
412			return nil, nil
413		}
414		if jsonKind(raw) == "string" {
415			var s string
416			if err := json.Unmarshal(raw, &s); err == nil && values[s] {
417				return &s, nil
418			}
419		}
420		return nil, zodItemError(msg, property)
421	}
422	
423	// parseNullableEnum mirrors an OPTIONAL, NULLABLE `z.enum(values)` field returning
424	// a pointer: absent OR present null → nil (both bind SQL NULL via the repo's
425	// `?? null`); a listed string → the value; anything else → the enum message.
426	func parseNullableEnum(raw json.RawMessage, values map[string]bool, msg, property string) (*string, *apierrors.CustomError) {
427		if raw == nil || isJSONNull(raw) {
428			return nil, nil
429		}
430		if jsonKind(raw) == "string" {
431			var s string
432			if err := json.Unmarshal(raw, &s); err == nil && values[s] {
433				return &s, nil
434			}
435		}
436		return nil, zodItemError(msg, property)
437	}
438	
439	// parseNullableInt64NonNeg mirrors `z.number().int().nonnegative().nullable()
440	// .optional()` returning a *int64 (the column is BIGINT): absent OR present null
441	// → nil; non-number → "received X"; non-integer → "received number"; below 0 →
442	// too_small (>=0); else the value.
443	func parseNullableInt64NonNeg(raw json.RawMessage, property string) (*int64, *apierrors.CustomError) {
444		if raw == nil || isJSONNull(raw) {
445			return nil, nil
446		}
447		var f float64
448		if err := json.Unmarshal(raw, &f); err != nil {
449			return nil, zodItemError("Invalid input: expected number, received "+jsonKind(raw), property)
450		}
451		if math.IsInf(f, 0) || f != math.Trunc(f) {
452			return nil, zodItemError("Invalid input: expected int, received number", property)
453		}
454		if f < 0 {
455			return nil, zodItemError("Too small: expected number to be >=0", property)
456		}
457		v := int64(f)
458		return &v, nil
459	}
460	
461	// parseNullableOffsetDatetime mirrors `z.string().datetime({ offset: true })
462	// .nullable().optional()` returning a pointer to the validated ISO string (bound
463	// to the timestamptz): absent OR present null → nil; non-string → "received X"; a
464	// string failing the offset-datetime format → `Invalid ISO datetime`; else the
465	// value.
466	func parseNullableOffsetDatetime(raw json.RawMessage, property string) (*string, *apierrors.CustomError) {
467		if raw == nil || isJSONNull(raw) {
468			return nil, nil
469		}
470		var s string
471		if err := json.Unmarshal(raw, &s); err != nil {
472			return nil, zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
473		}
474		if !infractionOffsetDateTimeRe.MatchString(s) {
475			return nil, zodItemError("Invalid ISO datetime", property)
476		}
477		return &s, nil
478	}
479	
480	// parseNullableRecord mirrors `z.record(z.string(), z.unknown()).nullable()
481	// .optional()` returning the raw jsonb bytes (the repo binds `JSON.stringify(v ??
482	// {})`): absent OR present null → nil (→ the repo binds `{}`); a JSON object → the
483	// raw bytes; any other type → the record type error. `z.unknown()` accepts any
484	// value, so no per-key validation is needed.
485	func parseNullableRecord(raw json.RawMessage, property string) (json.RawMessage, *apierrors.CustomError) {
486		if raw == nil || isJSONNull(raw) {
487			return nil, nil
488		}
489		if jsonKind(raw) != "object" {
490			return nil, zodItemError("Invalid input: expected record, received "+jsonKind(raw), property)
491		}
492		return raw, nil
493	}
494	
495	// addNullableOffsetDatetimeField mirrors an OPTIONAL, NULLABLE
496	// `z.string().datetime({ offset: true })` PATCH field: absent → skip; present
497	// null → set NULL; non-string → "received X"; a string failing the
498	// offset-datetime format → `Invalid ISO datetime`; else set the
499	// (timestamptz-bindable) string.
500	func addNullableOffsetDatetimeField(set map[string]any, col string, raw json.RawMessage, property string) *apierrors.CustomError {
501		if raw == nil {
502			return nil
503		}
504		if isJSONNull(raw) {
505			set[col] = nil
506			return nil
507		}
508		var s string
509		if err := json.Unmarshal(raw, &s); err != nil {
510			return zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
511		}
512		if !infractionOffsetDateTimeRe.MatchString(s) {
513			return zodItemError("Invalid ISO datetime", property)
514		}
515		set[col] = s
516		return nil
517	}
