// ParseInfractionDeleteByUser mirrors `infractionDeleteByUserQuery`
// (`{ bot_id: z.string().min(1), guild_id: z.string().min(1),
// user_id: z.string().min(1) }` — all required). Shape order: bot_id, guild_id,
// user_id. Backs the `delinfs` bulk delete.
func ParseInfractionDeleteByUser(botID, guildID, userID string) (string, string, string, *apierrors.CustomError) {
	if verr := validateStringLen(botID, "bot_id", 1, 0); verr != nil {
		return "", "", "", verr
