// ─── PATCH /:id (update) ──────────────────────────────────────────────────

// ParseInfractionUpdate mirrors `infractionUpdateBody` (NOT strict; every field
// optional). Builds the present-columns map (a present null → a nil map value →
// SQL NULL). An empty body yields an empty map; the repo turns that into
// `findById(id)`, matching Node's `if sets.length === 0 return findById(id)`.
// Fields validate in zod declaration order: reason, duration_ms, expires_at,
// status, mechanism, applied_at, revoked_at, revoked_by, revoke_reason.
func ParseInfractionUpdate(body []byte) (map[string]any, *apierrors.CustomError) {
	var raw struct {
		Reason       json.RawMessage `json:"reason"`
		DurationMs   json.RawMessage `json:"duration_ms"`
		ExpiresAt    json.RawMessage `json:"expires_at"`
		Status       json.RawMessage `json:"status"`
		Mechanism    json.RawMessage `json:"mechanism"`
		AppliedAt    json.RawMessage `json:"applied_at"`
		RevokedAt    json.RawMessage `json:"revoked_at"`
		RevokedBy    json.RawMessage `json:"revoked_by"`
		RevokeReason json.RawMessage `json:"revoke_reason"`
	}
	if err := json.Unmarshal(body, &raw); err != nil {
		return nil, bodyBindError(err)
	}
	set := map[string]any{}
	// reason: z.string().max(2000).nullable().optional().
	if verr := addMetaStringField(set, "reason", raw.Reason, "reason", 2000, false); verr != nil {
		return nil, verr
	}
	// duration_ms: z.number().int().nonnegative().nullable().optional().
	if verr := addNullableIntField(set, "duration_ms", raw.DurationMs, "duration_ms", 0, 0); verr != nil {
		return nil, verr
	}
	// expires_at: z.string().datetime({ offset: true }).nullable().optional().
	if verr := addNullableOffsetDatetimeField(set, "expires_at", raw.ExpiresAt, "expires_at"); verr != nil {
		return nil, verr
	}
	// status: z.enum(statusValues).optional() (NOT nullable → present null is an enum error).
	if verr := addOptionalEnumField(set, "status", raw.Status, infractionStatusSet, infractionStatusMsg, "status"); verr != nil {
		return nil, verr
	}
	// mechanism: z.enum(mechanismValues).nullable().optional().
	if verr := addNullableEnumField(set, "mechanism", raw.Mechanism, infractionMechanismSet, infractionMechanismMsg, "mechanism"); verr != nil {
		return nil, verr
	}
	// applied_at / revoked_at: z.string().datetime({ offset: true }).nullable().optional().
	if verr := addNullableOffsetDatetimeField(set, "applied_at", raw.AppliedAt, "applied_at"); verr != nil {
		return nil, verr
	}
	if verr := addNullableOffsetDatetimeField(set, "revoked_at", raw.RevokedAt, "revoked_at"); verr != nil {
		return nil, verr
	}
	// revoked_by: z.string().max(32).nullable().optional().
	if verr := addMetaStringField(set, "revoked_by", raw.RevokedBy, "revoked_by", 32, false); verr != nil {
		return nil, verr
	}
	// revoke_reason: z.string().max(2000).nullable().optional().
	if verr := addMetaStringField(set, "revoke_reason", raw.RevokeReason, "revoke_reason", 2000, false); verr != nil {
		return nil, verr
	}
	return set, nil
}

// ─── field helpers (moderation-specific) ──────────────────────────────────

// parseNullableBoundedString mirrors an OPTIONAL, NULLABLE `z.string()[.min][.max]`
// field returning a pointer: absent OR present null → nil (→ the repo binds SQL
// NULL, since absent and null both feed the Node repo's `?? null`); wrong type →
// "received X"; then the length bounds; else the value. A minLen/maxLen of 0
// disables that bound.
func parseNullableBoundedString(raw json.RawMessage, property string, minLen, maxLen int) (*string, *apierrors.CustomError) {
	if raw == nil || isJSONNull(raw) {
		return nil, nil
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return nil, zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
	}
	if verr := validateStringLen(s, property, minLen, maxLen); verr != nil {
		return nil, verr
	}
	return &s, nil
}

// parseOptionalEnum mirrors an OPTIONAL, non-nullable `z.enum(values)` field
// returning a pointer: absent → nil; a listed string → the value; anything else
// (including a present null) → the enum message.
func parseOptionalEnum(raw json.RawMessage, values map[string]bool, msg, property string) (*string, *apierrors.CustomError) {
	if raw == nil {
		return nil, nil
	}
	if jsonKind(raw) == "string" {
		var s string
		if err := json.Unmarshal(raw, &s); err == nil && values[s] {
			return &s, nil
		}
	}
	return nil, zodItemError(msg, property)
}

// parseNullableEnum mirrors an OPTIONAL, NULLABLE `z.enum(values)` field returning
// a pointer: absent OR present null → nil (both bind SQL NULL via the repo's
// `?? null`); a listed string → the value; anything else → the enum message.
func parseNullableEnum(raw json.RawMessage, values map[string]bool, msg, property string) (*string, *apierrors.CustomError) {
	if raw == nil || isJSONNull(raw) {
		return nil, nil
	}
	if jsonKind(raw) == "string" {
		var s string
		if err := json.Unmarshal(raw, &s); err == nil && values[s] {
			return &s, nil
		}
	}
	return nil, zodItemError(msg, property)
}

// parseNullableInt64NonNeg mirrors `z.number().int().nonnegative().nullable()
// .optional()` returning a *int64 (the column is BIGINT): absent OR present null
// → nil; non-number → "received X"; non-integer → "received number"; below 0 →
// too_small (>=0); else the value.
func parseNullableInt64NonNeg(raw json.RawMessage, property string) (*int64, *apierrors.CustomError) {
	if raw == nil || isJSONNull(raw) {
		return nil, nil
	}
	var f float64
	if err := json.Unmarshal(raw, &f); err != nil {
		return nil, zodItemError("Invalid input: expected number, received "+jsonKind(raw), property)
	}
	if math.IsInf(f, 0) || f != math.Trunc(f) {
		return nil, zodItemError("Invalid input: expected int, received number", property)
	}
	if f < 0 {
		return nil, zodItemError("Too small: expected number to be >=0", property)
	}
	v := int64(f)
	return &v, nil
}

// parseNullableOffsetDatetime mirrors `z.string().datetime({ offset: true })
// .nullable().optional()` returning a pointer to the validated ISO string (bound
// to the timestamptz): absent OR present null → nil; non-string → "received X"; a
// string failing the offset-datetime format → `Invalid ISO datetime`; else the
// value.
func parseNullableOffsetDatetime(raw json.RawMessage, property string) (*string, *apierrors.CustomError) {
	if raw == nil || isJSONNull(raw) {
		return nil, nil
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return nil, zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
	}
	if !infractionOffsetDateTimeRe.MatchString(s) {
		return nil, zodItemError("Invalid ISO datetime", property)
	}
	return &s, nil
}

// parseNullableRecord mirrors `z.record(z.string(), z.unknown()).nullable()
// .optional()` returning the raw jsonb bytes (the repo binds `JSON.stringify(v ??
// {})`): absent OR present null → nil (→ the repo binds `{}`); a JSON object → the
// raw bytes; any other type → the record type error. `z.unknown()` accepts any
// value, so no per-key validation is needed.
func parseNullableRecord(raw json.RawMessage, property string) (json.RawMessage, *apierrors.CustomError) {
	if raw == nil || isJSONNull(raw) {
		return nil, nil
	}
	if jsonKind(raw) != "object" {
		return nil, zodItemError("Invalid input: expected record, received "+jsonKind(raw), property)
	}
	return raw, nil
}

// addNullableOffsetDatetimeField mirrors an OPTIONAL, NULLABLE
// `z.string().datetime({ offset: true })` PATCH field: absent → skip; present
// null → set NULL; non-string → "received X"; a string failing the
// offset-datetime format → `Invalid ISO datetime`; else set the
// (timestamptz-bindable) string.
func addNullableOffsetDatetimeField(set map[string]any, col string, raw json.RawMessage, property string) *apierrors.CustomError {
	if raw == nil {
		return nil
	}
	if isJSONNull(raw) {
		set[col] = nil
		return nil
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
	}
	if !infractionOffsetDateTimeRe.MatchString(s) {
		return zodItemError("Invalid ISO datetime", property)
	}
	set[col] = s
	return nil
}
